def ico(name): return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{icons[name]}</svg>'
def button(text,href='/contact/',secondary=False): return f'<a class="button {"button-outline" if secondary else ""}" href="{href}">{text} {ico("arrow")}</a>'
