faqs=[('Which services can I discuss with Adox Global Ventures?','You can contact us about SEO and Google Business Profile optimisation, social media management, website development, Google and Meta advertising, branding and visual content. We will discuss what fits your goals before agreeing a scope.'),('Do you work with businesses in Oman?','The Oman website is for Adox Global Ventures in Muscat. You can reach the Oman team at +968 9696 7420 or info@adoxglobal.om.'),('How do we get started?','Tell us about your business, your current website or social pages, and what you would like to improve. We can then discuss priorities, deliverables and the next steps.'),('Can you improve my existing website?','Website improvements can include mobile usability, content, page structure, search optimisation and clearer contact paths. The right approach depends on the condition of the existing website and the scope agreed with you.'),('How long does digital marketing take to show results?','Timing varies by channel, competition, budget and the starting point of your business. SEO generally needs ongoing work, while paid campaigns can provide earlier feedback. Results are not guaranteed; goals and reporting should be agreed for your project.'),('How much do your services cost?','Costs depend on the work required. Contact us with your requirements so the scope and budget can be discussed. No package price is assumed on this website.'),('How does the enquiry form work?','The form prepares an email containing your details. You review it in your own email app and send it when ready. The form does not automatically submit or store your details.'),('How do I visit the India or Dubai website?','Use the country selector at the top of the website. India opens adoxglobal.com; Dubai, UAE opens adoxglobal.com/ae. Oman keeps you on this website.')]
save('faq',page('Frequently Asked Questions','Answers to common questions about working with Adox Global Ventures in Oman.',titleband('Frequently asked questions','A Few Things<br> You May Want to Know.','Clear answers before we start the conversation.')+'<section class="section"><div class="container narrow faq-list">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faqs)+'</div></section>'+cta(),'FAQ'))
articles=[
('local-search-oman','Local Search','Help Customers Find Your Business in Oman','A useful starting checklist for a clear, consistent local search presence.', [('Keep your business details consistent','Use the same business name, phone number and accurate address across your website and business profiles. Update details when they change.'),('Complete your Google Business Profile','Choose relevant categories, describe your services clearly, and add current photos. Keep opening hours accurate, including holiday changes.'),('Make your website locally useful','Explain the services you provide, the area you serve and the easiest way to contact you. Write for customers rather than repeating place names.'),('Review the customer journey','Check the full path from a search result to your website and then to a call or enquiry. A visible phone number and a clear mobile layout can make that journey simpler.')]),
('mobile-website-checklist','Website Experience','Is Your Website Ready for Mobile Visitors?','Five practical details to review before your next website update.',[('Make the next step obvious','Every key page should explain what a visitor can do next, whether that is calling, asking a question or viewing your services.'),('Keep the content easy to scan','Use clear headings, short paragraphs and enough space around buttons. Avoid making visitors pinch and zoom to understand your page.'),('Test real contact links','Check that phone buttons dial the correct number and email links open the right address. A beautiful page is less useful if its contact path is broken.'),('Use images with a purpose','Choose relevant images, keep file sizes sensible and provide descriptions where images carry meaning. Decorative graphics should not slow down the page.'),('Check it on different screens','Review navigation, forms and longer pages on a phone as well as a desktop. Look for clipped text and horizontal scrolling.')]),
('campaign-goals','Campaign Planning','Start Your Campaign with a Clear Goal','Connect your audience, offer and measurement before you launch.',[('Choose the outcome first','Decide what the campaign should help people do. Calls, enquiries and online purchases require different messages and different measurement.'),('Know the audience','Define whom you need to reach, what they are looking for and what could stop them from taking the next step. Keep the message relevant to them.'),('Align the advert and the landing page','The offer and next step should remain consistent after someone clicks. Avoid sending every campaign to a generic page if a focused landing page would answer the question better.'),('Agree the budget and review plan','Set the spending limit, choose the signals to review and decide when to make changes. Avoid judging a campaign by likes or impressions alone.')])]
